const msg = ($input.first().json.message?.text || '').trim().toLowerCase();
const chatId = $input.first().json.message?.chat?.id || '';
let type = 'other';
let originalText = $input.first().json.message?.text || '';

if (msg === 'approve' || msg === 'موافق') type = 'approve';
else if (msg === 'export' || msg === 'صدر' || msg === 'تصدير') type = 'export';
else if (msg === 'post' || msg === 'انشر' || msg === 'نشر') type = 'post';
else if (msg === 'أخبار' || msg === 'اخبار' || msg === 'news' || msg === 'عالمي' || msg === 'عالمية' || msg === 'بحث' || msg === 'world') type = 'news';
else if (/^\d+$/.test(msg) && parseInt(msg) >= 1 && parseInt(msg) <= 10) {
  const pickNum = parseInt(msg);
  const staticData = $getWorkflowStaticData('global');
  const cached = staticData.newsCache;
  const cacheAge = Date.now() - (staticData.newsCacheAt || 0);
  if (cached && cacheAge < 3600000 && pickNum <= cached.length) {
    const chosen = cached[pickNum - 1];
    let fullContent = '';
    try {
      const page = await this.helpers.httpRequest({ method: 'GET', url: chosen.link, headers: { 'Accept': 'text/html' } });
      let body = page;
      const articleMatch = body.match(/<article[^>]*>(.*?)<\/article>/s) || body.match(/<div[^>]*class="[^"]*(?:entry-content|post-content|article-content|content-area)[^"]*"[^>]*>(.*?)<\/div>/s);
      if (articleMatch) body = articleMatch[1];
      body = body.replace(/<script[^>]*>.*?<\/script>/gs, '').replace(/<style[^>]*>.*?<\/style>/gs, '').replace(/<[^>]*>/g, ' ').replace(/&[^;]+;/g, ' ').replace(/\s+/g, ' ').trim();
      fullContent = body.substring(0, 2000);
    } catch(e) { fullContent = chosen.desc; }
    originalText = 'اكتب كاروسيل عن هالخبر. لخص النقاط المهمة واذا في خطوات وضحها بشكل مختصر:\n\nالعنوان: ' + chosen.title + '\n\nالمحتوى الكامل:\n' + fullContent + '\n\nالمصدر: ' + chosen.link;
    type = 'topic';
    return [{ json: { type, originalText, chatId } }];
  }
  // Fallback: re-fetch if no cache
  const RSS_FEEDS = [
  'https://www.mentalfloss.com/rss.xml',
  'https://www.smithsonianmag.com/rss/latest_articles/',
  'https://www.iflscience.com/rss',
  'https://www.openculture.com/feed',
  'https://bigthink.com/feed/',
  'https://www.sciencedaily.com/rss/all.xml',
  'https://www.atlasobscura.com/feeds/latest',
  'http://feeds.bbci.co.uk/news/world/rss.xml',
  'https://feeds.npr.org/1001/rss.xml',
  'https://lithub.com/feed/'
];
  const allArticles = [];
  for (const feedUrl of RSS_FEEDS) {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET', url: feedUrl,
        headers: { 'Accept': 'application/rss+xml, application/xml, text/xml' }
      });
      const xml = typeof res === 'string' ? res : JSON.stringify(res);
      const items = xml.split('<item>').slice(1, 8);
      for (const item of items) {
        const titleMatch = item.match(/<title><!\[CDATA\[(.+?)\]\]>|<title>(.+?)<\/title>/);
        const linkMatch = item.match(/<link>(.+?)<\/link>|<link><!\[CDATA\[(.+?)\]\]>/);
        const descMatch = item.match(/<description><!\[CDATA\[(.+?)\]\]>|<description>(.+?)<\/description>/s);
        const dateMatch = item.match(/<pubDate>(.+?)<\/pubDate>/);
        const contentMatch = item.match(/<content:encoded><!\[CDATA\[(.+?)\]\]>/s);
        const title = (titleMatch ? (titleMatch[1] || titleMatch[2]) : '').trim();
        const link = (linkMatch ? (linkMatch[1] || linkMatch[2]) : '').trim();
        let desc = (descMatch ? (descMatch[1] || descMatch[2]) : '').trim();
        desc = desc.replace(/<[^>]*>/g, '').replace(/&[^;]+;/g, ' ').substring(0, 120).trim();
        const pubDate = dateMatch ? new Date(dateMatch[1]).getTime() : 0;
        const source = (function(){ try { return feedUrl.split('/')[2].replace('www.','').split('.')[0]; } catch(e){ return 'مصدر'; } })();
        if (title && link) allArticles.push({ title, link, desc, pubDate, source });
      }
    } catch (e) {}
  }
  allArticles.sort((a, b) => b.pubDate - a.pubDate);
  const top5 = allArticles.slice(0, 10);
  if (pickNum <= top5.length) {
    const chosen = top5[pickNum - 1];

    // Fetch full article content
    let fullContent = '';
    try {
      const page = await this.helpers.httpRequest({
        method: 'GET', url: chosen.link,
        headers: { 'Accept': 'text/html' }
      });
      // Extract text from article body
      let body = page;
      // Try to find article/post content area
      const articleMatch = body.match(/<article[^>]*>(.*?)<\/article>/s) || 
                           body.match(/<div[^>]*class="[^"]*(?:entry-content|post-content|article-content|content-area)[^"]*"[^>]*>(.*?)<\/div>/s);
      if (articleMatch) body = articleMatch[1];
      // Remove scripts, styles, tags
      body = body.replace(/<script[^>]*>.*?<\/script>/gs, '');
      body = body.replace(/<style[^>]*>.*?<\/style>/gs, '');
      body = body.replace(/<[^>]*>/g, ' ');
      body = body.replace(/&[^;]+;/g, ' ');
      body = body.replace(/\s+/g, ' ').trim();
      fullContent = body.substring(0, 2000);
    } catch (e) {
      fullContent = chosen.desc;
    }

    originalText = 'اكتب كاروسيل عن هالخبر. لخص النقاط المهمة واذا في خطوات وضحها بشكل مختصر:\n\nالعنوان: ' + chosen.title + '\n\nالمحتوى الكامل:\n' + fullContent + '\n\nالمصدر: ' + chosen.link;
    type = 'topic';
  }
}
else if (/^s\d+:/i.test(msg) || /^caption:/i.test(msg) || /^hashtags:/i.test(msg)) type = 'edit';
else if (msg === 'أفكار' || msg === 'افكار' || msg === 'اقتراحات' || msg === 'مواضيع' || msg === 'ideas' || msg === 'suggest') type = 'ideas';
else if (msg.length > 2) type = 'topic';

return [{ json: { type, originalText, chatId } }];

function extractText(value) {
  // نص عادي
  if (typeof value === 'string') {
    return value;
  }

  // مصفوفة Claude content blocks
  if (Array.isArray(value)) {
    const textBlock = value.find(
      block =>
        block &&
        block.type === 'text' &&
        typeof block.text === 'string'
    );

    return textBlock?.text || '';
  }

  // كائن يحتوي على content
  if (value && typeof value === 'object') {
    if (typeof value.text === 'string') {
      return value.text;
    }

    if (value.content !== undefined) {
      return extractText(value.content);
    }
  }

  return '';
}

let raw = '';

// أولًا: نحاول قراءة النص المحفوظ في Google Sheets
try {
  const sheetData = $('Save to Sheet').first().json;
  raw = extractText(sheetData.content);
} catch (error) {
  raw = '';
}

// إذا لم يوجد نص صالح في الجدول، نقرأ مباشرة من Claude
if (!raw) {
  try {
    const aiResponse = $('Claude Content API').first().json;
    raw = extractText(aiResponse.content);
  } catch (error) {
    raw = '';
  }
}

// Fallback من مدخل العقدة الحالي
if (!raw) {
  raw = extractText($input.first().json);
}

if (!raw || typeof raw !== 'string') {
  throw new Error(
    'لم يتم العثور على النص النهائي في رد Claude. تأكد أن الرد يحتوي على block من النوع text.'
  );
}

// تنظيف code fences في حال رجع JSON داخل Markdown
raw = raw
  .trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');

if (start === -1 || end === -1 || end <= start) {
  throw new Error(
    'رد Claude لا يحتوي على JSON صالح.\n\nبداية الرد:\n' +
    raw.slice(0, 500)
  );
}

let content;

try {
  content = JSON.parse(raw.slice(start, end + 1));
} catch (error) {
  throw new Error(
    'تعذر تحليل JSON الصادر من Claude: ' +
    error.message +
    '\n\nبداية الرد:\n' +
    raw.slice(0, 700)
  );
}

if (!Array.isArray(content.slides) || content.slides.length === 0) {
  throw new Error('JSON صالح، لكن لا توجد سلايدات داخل slides.');
}

const topic = content.topic || 'موضوع جديد';
const slideCount = content.slides.length;

let preview = '✨ جاهز كاروسيلك من فطين!\n\n';
preview += '📌 الموضوع: ' + topic + '\n';
preview += '🔢 عدد السلايدات: ' + slideCount + '\n\n';

content.slides.forEach((s, i) => {
  preview += '━━━ سلايد ' + (i + 1) + ' (' + (s.type || 'unknown') + ') ━━━\n';

  if (s.type === 'cover') {
    if (s.eyebrow) {
      preview += s.eyebrow + '\n';
    }

    preview += [
      s.title_line1,
      s.title_line2_grad,
      s.title_line3
    ]
      .filter(Boolean)
      .join(' ') + '\n';

    if (s.pill) {
      preview += '🏷 ' + s.pill + '\n';
    }
  }

  else if (s.type === 'stat') {
    preview += '🔢 ' + (s.number || '') + '\n';
    preview += '📍 ' + (s.label || '') + '\n';

    if (s.description) {
      preview += s.description + '\n';
    }
  }

  else if (s.type === 'how_to') {
    preview += '📝 ' + (s.title || '') + '\n';

    (s.steps || []).forEach((step, j) => {
      preview += (j + 1) + '. ' + step + '\n';
    });
  }

  else if (s.type === 'why_matters') {
    preview += '💡 ' + (s.title || '') + '\n';

    (s.points || []).forEach((point, j) => {
      preview += (j + 1) + '. ' + point + '\n';
    });
  }

  else if (s.type === 'save') {
    preview += '🔖 احفظ هالمعلومات:\n';

    (s.points || []).forEach((point, j) => {
      preview += (j + 1) + '. ' + point + '\n';
    });
  }

  else if (s.type === 'warning') {
    preview += '⚠️ ' + (s.title || 'انتبه!') + '\n';

    (s.points || []).forEach((point, j) => {
      preview += (j + 1) + '. ' + point + '\n';
    });
  }

  else if (s.type === 'one_liner') {
    preview += '💬 ' + (s.text || '') + '\n';
  }

  else if (s.type === 'quote') {
    preview += '💬 "' + (s.quote || '') + '"\n';

    if (s.author) {
      preview += '— ' + s.author;

      if (s.role) {
        preview += ' (' + s.role + ')';
      }

      preview += '\n';
    }
  }

  else if (s.type === 'comparison') {
    preview +=
      (s.col1_header || 'الأول') +
      ' vs ' +
      (s.col2_header || 'الثاني') +
      '\n';

    (s.rows || []).forEach(row => {
      if (Array.isArray(row)) {
        preview +=
          '• ' +
          (row[0] || '') +
          ' | ' +
          (row[1] || '') +
          '\n';
      }
    });
  }

  else if (s.type === 'action_prompt') {
    preview += '📣 ' + (s.headline || '') + '\n';
    preview += 'الإجراء: ' + (s.action || 'save') + '\n';
  }

  else if (s.type === 'cta') {
    preview += '❓ ' + (s.question || '') + '\n';

    if (
      Array.isArray(s.options) &&
      s.options.length
    ) {
      s.options.forEach((option, j) => {
        preview +=
          String.fromCharCode(65 + j) +
          ') ' +
          option +
          '\n';
      });
    }

    else if (s.cta_style === 'poll') {
      preview +=
        'A) ' + (s.poll_left || 'موافق') + '\n';

      preview +=
        'B) ' + (s.poll_right || 'مو موافق') + '\n';
    }
  }

  preview += '\n';
});

if (content.caption) {
  preview +=
    '━━━ الكابشن ━━━\n' +
    content.caption +
    '\n\n';
}

if (content.hashtags) {
  preview +=
    '━━━ الهاشتاقات ━━━\n' +
    content.hashtags +
    '\n\n';
}

preview +=
  '━━━━━━━━━━\n' +
  '✅ عجبك؟ أرسل: موافق\n\n' +
  '✏️ تبي تعدّل؟\n' +
  's2: القديم > الجديد\n' +
  'caption: كابشن جديد';

return [
  {
    json: {
      preview,
      chatId: $('Telegram Trigger').first().json.message.chat.id,
      contentJson: JSON.stringify(content),
      topic,
      slideCount,
      caption: content.caption || '',
      hashtags: content.hashtags || ''
    }
  }
];

const items = $input.all();
let lastDraft = null;
let lastIndex = -1;
for (let i = items.length - 1; i >= 0; i--) {
  if (items[i].json.status === 'draft') {
    lastDraft = items[i].json;
    lastIndex = i + 2; // +2 because sheets are 1-indexed and header row
    break;
  }
}
if (!lastDraft) throw new Error('No draft rows found');
return [{ json: { ...lastDraft, rowIndex: lastIndex, contentJson: lastDraft['content'] } }];

// ===== Fateen "تعرف؟" cinematic FULL-BLEED design system =====
const BRAND = { bg1:'#06111E', bg2:'#081827', lime:'#B7F000', white:'#FFFFFF', sub:'#D9D9D9', line:'rgba(183,240,0,0.30)' };
const arNums = ['١','٢','٣','٤','٥','٦','٧','٨','٩','١٠'];

function esc(v){ return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

const BRUSH = "data:image/svg+xml;base64," + Buffer.from(
 `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 300 100' preserveAspectRatio='none'><path d='M5,52 C5,26 26,14 70,12 C140,9 200,10 250,14 C286,17 297,26 296,52 C295,80 280,90 230,90 C160,90 90,92 55,88 C20,84 5,78 5,52 Z' fill='${BRAND.lime}'/></svg>`
).toString('base64');

function highlight(text, word){
  text = esc(text); if(!word) return text; const w = esc(word);
  return text.includes(w) ? text.replace(w, `<span class="brush">${w}</span>`) : text;
}

// free AI image (Pollinations) from image_prompt, or explicit url, else '' (gradient fallback)
function aiImage(slide, idx){
  const direct = slide.image_url || slide.visual_url || slide.background_image;
  if(direct) return String(direct);
  const p = slide.image_prompt || '';
  if(!p) return '';
  const full = p + ', hyper realistic, ultra detailed, 8K, cinematic lighting, volumetric light, depth of field, dark cinematic background, no text';
  const seed = (Math.abs(Array.from(p).reduce((a,c)=>a+c.charCodeAt(0),0)) + (idx||0)*761) % 100000;
  return 'https://image.pollinations.ai/prompt/' + encodeURIComponent(full) + '?width=1080&height=1350&nologo=true&model=flux&seed=' + seed;
}

function bgLayer(slide, idx){
  const url = aiImage(slide, idx);
  if(url){
    return `<div class="bg" style="background-image:url('${esc(url)}')"></div>`;
  }
  // consistent background: only the first slide differs, the rest are identical
  return `<div class="bg fallback ${idx===0?'cover':''}"></div>`;
}

function chrome(idx, N, data){
  const ep = data.episode_number || data.episode || '';
  const epTxt = ep ? ('الحلقة ' + String(ep).padStart(3,'0')) : 'سلسلة تعرف؟';
  const swipe = idx < N-1
    ? `<div class="swipe"><span>اسحب</span><svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="${BRAND.lime}" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14"/><path d="M13 6l6 6-6 6"/></svg></div>` : '';
  let segs=''; for(let i=0;i<N;i++) segs+=`<span class="seg ${i<=idx?'on':''}"></span>`;
  return `<div class="progress">${segs}</div>
    <div class="logo"><div class="logo-ar">فطين</div><div class="logo-en">FATEEN</div></div>
    <div class="episode"><div class="ep-name">${esc(epTxt)}</div><div class="ep-count"><span class="brush">${idx+1}/${N}</span></div></div>
    ${swipe}`;
}

function points(arr){
  return (arr||[]).slice(0,3).map((p,i)=>
    `<div class="pt"><span class="pt-n">${arNums[i]||i+1}</span><span class="pt-t">${esc(p)}</span></div>`).join('');
}

function renderBody(slide){
  const t = slide.type; let kicker='تعرف؟', head='', sub='', extra='';
  if(t==='cover'){
    kicker = slide.eyebrow || 'تعرف؟';
    const l1=slide.title_line1||'', l2=slide.title_line2_grad||'', l3=slide.title_line3||'';
    head = [l1? esc(l1):'', l2?`<span class="brush">${esc(l2)}</span>`:'', l3?esc(l3):''].filter(Boolean).join('<br>');
    if(slide.pill) sub = esc(slide.pill);
  } else if(t==='stat'){
    kicker='رقم يوقفك';
    head = `<span class="lime big">${esc(slide.number||'')}</span><br>${esc(slide.label||'')}`;
    if(slide.description) sub = esc(slide.description);
  } else if(t==='one_liner'){ kicker='الخلاصة'; head = highlight(slide.text||'', slide.grad_word);
  } else if(t==='why_matters'||t==='how_to'||t==='save'||t==='warning'){
    kicker = t==='why_matters'?'ليش يهمك؟':t==='how_to'?'كيف؟':t==='save'?'احفظها':'انتبه';
    head = esc(slide.title || (t==='save'?'احفظ هذي':''));
    extra = `<div class="pts">${points(slide.points||slide.steps)}</div>`;
  } else if(t==='comparison'){
    kicker='قارن';
    head = `<span class="lime">${esc(slide.col1_header||'')}</span> ⟷ ${esc(slide.col2_header||'')}`;
    extra = `<div class="pts">${(slide.rows||[]).slice(0,3).map(r=>`<div class="pt"><span class="pt-t">${esc(r[0])}</span><span class="vs">|</span><span class="pt-t">${esc(r[1])}</span></div>`).join('')}</div>`;
  } else if(t==='quote'){
    kicker='قيل'; head = `<span class="qm">“</span>${esc(slide.quote||'')}`;
    if(slide.author) sub = '— ' + esc(slide.author) + (slide.role?' · '+esc(slide.role):'');
  } else if(t==='action_prompt'){
    const m={save:'احفظ المنشور',share:'شارك المنشور',like:'عجبك؟'}; kicker='قبل تكمل';
    head = highlight(slide.headline || m[slide.action] || m.save, slide.action==='save'?'احفظ':slide.action==='share'?'شارك':'');
  } else if(t==='cta'){
    kicker='دورك'; head = highlight(slide.question||'وش رأيك؟', slide.grad_phrase); sub='اكتب جوابك في التعليقات';
  } else head = esc(slide.type||'');

  const plain = String(head).replace(/<[^>]+>/g,'');
  const hc = plain.length>30?'h-sm':plain.length>16?'h-md':'';
  return `<div class="content">
    <div class="kicker">${esc(kicker)}</div>
    <h1 class="head ${hc}">${head}</h1>
    ${sub?`<div class="sub">${sub}</div>`:''}
    ${extra}
  </div>`;
}

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Tajawal:wght@400;500;700;800;900&family=Cairo:wght@600;700;900&display=swap');
*{margin:0;padding:0;box-sizing:border-box}
.stage{position:relative;width:1080px;height:1350px;overflow:hidden;direction:rtl;font-family:'Tajawal','Cairo',sans-serif;
  background:linear-gradient(160deg,${BRAND.bg1},${BRAND.bg2} 60%,#04101a);color:${BRAND.white}}
.progress{position:absolute;top:26px;left:64px;right:64px;z-index:41;display:flex;gap:7px}
.progress .seg{flex:1;height:6px;border-radius:6px;background:rgba(255,255,255,.20)}
.progress .seg.on{background:${BRAND.lime};box-shadow:0 0 12px rgba(183,240,0,.45)}
.bg{position:absolute;inset:0;background-size:cover;background-position:center;z-index:0}
.bg.fallback{background:
  radial-gradient(70% 50% at 68% 30%, rgba(60,110,140,.22), transparent 58%),
  radial-gradient(60% 45% at 28% 90%, rgba(183,240,0,.08), transparent 60%),
  linear-gradient(160deg,#06111E,#081827 55%,#04101a)}
.bg.fallback.cover{background:
  radial-gradient(82% 55% at 60% 28%, rgba(90,160,190,.30), transparent 58%),
  radial-gradient(72% 50% at 24% 92%, rgba(183,240,0,.15), transparent 60%),
  linear-gradient(160deg,#06111E,#0a2030 50%,#04101a)}
/* single centered scrim for consistent legibility on every slide */
.stage::before{content:'';position:absolute;inset:0;z-index:1;pointer-events:none;
  background:
    radial-gradient(78% 56% at 50% 52%, rgba(4,11,19,.86), rgba(4,11,19,.42) 55%, rgba(4,11,19,.10) 100%),
    linear-gradient(180deg, rgba(6,17,30,.62) 0%, transparent 20%, transparent 76%, rgba(4,11,19,.82) 100%)}
.stage::after{content:'';position:absolute;inset:0;z-index:1;pointer-events:none;box-shadow:inset 0 0 280px rgba(0,0,0,.6)}
/* chrome */
.logo{position:absolute;top:56px;left:64px;z-index:40;direction:ltr;text-align:left;text-shadow:0 2px 14px rgba(0,0,0,.7)}
.logo-ar{font-size:40px;font-weight:900;letter-spacing:-1px;color:#fff;line-height:1}
.logo-en{font-size:19px;font-weight:700;letter-spacing:7px;color:${BRAND.sub};margin-top:4px}
.episode{position:absolute;top:56px;right:64px;z-index:40;text-align:center;text-shadow:0 2px 14px rgba(0,0,0,.7)}
.ep-name{font-size:24px;font-weight:700;color:#fff;letter-spacing:.5px}
.ep-count{margin-top:12px;display:flex;justify-content:flex-end}
.ep-count .brush{font-size:24px;padding:4px 20px}
.swipe{position:absolute;bottom:56px;right:64px;z-index:40;display:flex;align-items:center;gap:10px;color:${BRAND.lime};font-size:26px;font-weight:800;text-shadow:0 2px 12px rgba(0,0,0,.8)}
