// ===== Fateen "تعرف؟" cinematic FULL-BLEED design system =====
const BRAND = { bg1:'#06111E', bg2:'#081827', lime:'#B7F000', white:'#FFFFFF', sub:'#D9D9D9', line:'rgba(183,240,0,0.30)' };
const arNums = ['١','٢','٣','٤','٥','٦','٧','٨','٩','١٠'];

function esc(v){ return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

const BRUSH = "data:image/svg+xml;base64," + Buffer.from(
 `<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 300 100' preserveAspectRatio='none'><path d='M5,52 C5,26 26,14 70,12 C140,9 200,10 250,14 C286,17 297,26 296,52 C295,80 280,90 230,90 C160,90 90,92 55,88 C20,84 5,78 5,52 Z' fill='${BRAND.lime}'/></svg>`
).toString('base64');

function highlight(text, word){
  text = esc(text); if(!word) return text; const w = esc(word);
  return text.includes(w) ? text.replace(w, `<span class="brush">${w}</span>`) : text;
}

// free AI image (Pollinations) from image_prompt, or explicit url, else '' (gradient fallback)
function aiImage(slide, idx){
  const direct = slide.image_url || slide.visual_url || slide.background_image;
  if(direct) return String(direct);
  const p = slide.image_prompt || '';
  if(!p) return '';
  const full = p + ', hyper realistic, ultra detailed, 8K, cinematic lighting, volumetric light, depth of field, dark cinematic background, no text';
  const seed = (Math.abs(Array.from(p).reduce((a,c)=>a+c.charCodeAt(0),0)) + (idx||0)*761) % 100000;
  return 'https://image.pollinations.ai/prompt/' + encodeURIComponent(full) + '?width=1080&height=1350&nologo=true&model=flux&seed=' + seed;
}

function bgLayer(slide, idx){
  const url = aiImage(slide, idx);
  if(url){
    return `<div class="bg" style="background-image:url('${esc(url)}')"></div>`;
  }
  // consistent background: only the first slide differs, the rest are identical
  return `<div class="bg fallback ${idx===0?'cover':''}"></div>`;
}

function chrome(idx, N, data){
  const ep = data.episode_number || data.episode || '';
  const epTxt = ep ? ('الحلقة ' + String(ep).padStart(3,'0')) : 'سلسلة تعرف؟';
  const swipe = idx < N-1
    ? `<div class="swipe"><span>اسحب</span><svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="${BRAND.lime}" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14"/><path d="M13 6l6 6-6 6"/></svg></div>` : '';
  let segs=''; for(let i=0;i<N;i++) segs+=`<span class="seg ${i<=idx?'on':''}"></span>`;
  return `<div class="progress">${segs}</div>
    <div class="logo"><div class="logo-ar">فطين</div><div class="logo-en">FATEEN</div></div>
    <div class="episode"><div class="ep-name">${esc(epTxt)}</div><div class="ep-count"><span class="brush">${idx+1}/${N}</span></div></div>
    ${swipe}`;
}

function points(arr){
  return (arr||[]).slice(0,3).map((p,i)=>
    `<div class="pt"><span class="pt-n">${arNums[i]||i+1}</span><span class="pt-t">${esc(p)}</span></div>`).join('');
}

function renderBody(slide){
  const t = slide.type; let kicker='تعرف؟', head='', sub='', extra='';
  if(t==='cover'){
    kicker = slide.eyebrow || 'تعرف؟';
    const l1=slide.title_line1||'', l2=slide.title_line2_grad||'', l3=slide.title_line3||'';
    head = [l1? esc(l1):'', l2?`<span class="brush">${esc(l2)}</span>`:'', l3?esc(l3):''].filter(Boolean).join('<br>');
    if(slide.pill) sub = esc(slide.pill);
  } else if(t==='stat'){
    kicker='رقم يوقفك';
    head = `<span class="lime big">${esc(slide.number||'')}</span><br>${esc(slide.label||'')}`;
    if(slide.description) sub = esc(slide.description);
  } else if(t==='one_liner'){ kicker='الخلاصة'; head = highlight(slide.text||'', slide.grad_word);
  } else if(t==='why_matters'||t==='how_to'||t==='save'||t==='warning'){
    kicker = t==='why_matters'?'ليش يهمك؟':t==='how_to'?'كيف؟':t==='save'?'احفظها':'انتبه';
    head = esc(slide.title || (t==='save'?'احفظ هذي':''));
    extra = `<div class="pts">${points(slide.points||slide.steps)}</div>`;
  } else if(t==='comparison'){
    kicker='قارن';
    head = `<span class="lime">${esc(slide.col1_header||'')}</span> ⟷ ${esc(slide.col2_header||'')}`;
    extra = `<div class="pts">${(slide.rows||[]).slice(0,3).map(r=>`<div class="pt"><span class="pt-t">${esc(r[0])}</span><span class="vs">|</span><span class="pt-t">${esc(r[1])}</span></div>`).join('')}</div>`;
  } else if(t==='quote'){
    kicker='قيل'; head = `<span class="qm">“</span>${esc(slide.quote||'')}`;
    if(slide.author) sub = '— ' + esc(slide.author) + (slide.role?' · '+esc(slide.role):'');
  } else if(t==='action_prompt'){
    const m={save:'احفظ المنشور',share:'شارك المنشور',like:'عجبك؟'}; kicker='قبل تكمل';
    head = highlight(slide.headline || m[slide.action] || m.save, slide.action==='save'?'احفظ':slide.action==='share'?'شارك':'');
  } else if(t==='cta'){
    kicker='دورك'; head = highlight(slide.question||'وش رأيك؟', slide.grad_phrase); sub='اكتب جوابك في التعليقات';
  } else head = esc(slide.type||'');

  const plain = String(head).replace(/<[^>]+>/g,'');
  const hc = plain.length>30?'h-sm':plain.length>16?'h-md':'';
  return `<div class="content">
    <div class="kicker">${esc(kicker)}</div>
    <h1 class="head ${hc}">${head}</h1>
    ${sub?`<div class="sub">${sub}</div>`:''}
    ${extra}
  </div>`;
}

