try {
  const media = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://graph.instagram.com/v21.0/${published.id}?fields=permalink&access_token=${accessToken}`
  });
  permalink = media.permalink || '';
} catch(e) {}

return [{ json: { postId: published.id, carouselId: carousel.id, rowId, permalink } }];

