  'http://feeds.bbci.co.uk/news/world/rss.xml',
  'https://feeds.npr.org/1001/rss.xml',
  'https://lithub.com/feed/'
];

const allArticles = [];

for (const feedUrl of RSS_FEEDS) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: feedUrl,
      headers: { 'Accept': 'application/rss+xml, application/xml, text/xml' }
    });

    const xml = typeof res === 'string' ? res : JSON.stringify(res);
    const items = xml.split('<item>').slice(1, 8);

    for (const item of items) {
      const titleMatch = item.match(/<title><!\[CDATA\[(.+?)\]\]>|<title>(.+?)<\/title>/);
      const linkMatch = item.match(/<link>(.+?)<\/link>|<link><!\[CDATA\[(.+?)\]\]>/);
      const descMatch = item.match(/<description><!\[CDATA\[(.+?)\]\]>|<description>(.+?)<\/description>/s);
      const dateMatch = item.match(/<pubDate>(.+?)<\/pubDate>/);

      const title = (titleMatch ? (titleMatch[1] || titleMatch[2]) : '').trim();
      const link = (linkMatch ? (linkMatch[1] || linkMatch[2]) : '').trim();
      let desc = (descMatch ? (descMatch[1] || descMatch[2]) : '').trim();
      desc = desc.replace(/<[^>]*>/g, '').replace(/&[^;]+;/g, ' ').substring(0, 120).trim();
      const pubDate = dateMatch ? new Date(dateMatch[1]).getTime() : 0;
      const source = (function(){ try { return feedUrl.split('/')[2].replace('www.','').split('.')[0]; } catch(e){ return 'مصدر'; } })();
      if (title && link) {
        allArticles.push({ title, link, desc, pubDate, source });
      }
    }
  } catch (e) {
    // Skip failed feeds
  }
}

// Sort by date (newest first) and take top 5
allArticles.sort((a, b) => b.pubDate - a.pubDate);
const top5 = allArticles.slice(0, 10);

// Build the message
let msg = '🌍 أفكار من محتوى عالمي — منسوخة لك:\n\n';
top5.forEach((a, i) => {
  msg += (i + 1) + '️⃣ ' + a.title + '\n';
  msg += '📝 ' + a.desc + '\n';
  msg += '🔗 ' + a.link + '\n';
  msg += '📌 ' + a.source + '\n\n';
});
msg += '✍️ رد برقم الفكرة وأحوّلها لك كاروسيل عربي كامل!';

const staticData = $getWorkflowStaticData('global');
staticData.newsCache = top5;
staticData.newsCacheAt = Date.now();
return [{ json: { newsMessage: msg, articles: JSON.stringify(top5), chatId: $json.chatId } }];

// Pass articles data through for pickup by number
// Articles are stored in the Telegram message itself
// When user picks a number, we re-fetch and pick
return [{ json: { saved: true, articles: $json.articles, chatId: $json.chatId } }];

const pickNum = parseInt($json.originalText);
const chatId = $json.chatId;

// Re-fetch RSS to get the same articles
const RSS_FEEDS = [
  'https://www.mentalfloss.com/rss.xml',
  'https://www.smithsonianmag.com/rss/latest_articles/',
  'https://www.iflscience.com/rss',
  'https://www.openculture.com/feed',
  'https://bigthink.com/feed/',
  'https://www.sciencedaily.com/rss/all.xml',
  'https://www.atlasobscura.com/feeds/latest',
  'http://feeds.bbci.co.uk/news/world/rss.xml',
  'https://feeds.npr.org/1001/rss.xml',
  'https://lithub.com/feed/'
];

const allArticles = [];
for (const feedUrl of RSS_FEEDS) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: feedUrl,
      headers: { 'Accept': 'application/rss+xml, application/xml, text/xml' }
    });
    const xml = typeof res === 'string' ? res : JSON.stringify(res);
    const items = xml.split('<item>').slice(1, 8);
    for (const item of items) {
      const titleMatch = item.match(/<title><!\[CDATA\[(.+?)\]\]>|<title>(.+?)<\/title>/);
      const linkMatch = item.match(/<link>(.+?)<\/link>|<link><!\[CDATA\[(.+?)\]\]>/);
      const descMatch = item.match(/<description><!\[CDATA\[(.+?)\]\]>|<description>(.+?)<\/description>/s);
      const dateMatch = item.match(/<pubDate>(.+?)<\/pubDate>/);
      const title = (titleMatch ? (titleMatch[1] || titleMatch[2]) : '').trim();
      const link = (linkMatch ? (linkMatch[1] || linkMatch[2]) : '').trim();
      let desc = (descMatch ? (descMatch[1] || descMatch[2]) : '').trim();
      desc = desc.replace(/<[^>]*>/g, '').replace(/&[^;]+;/g, ' ').substring(0, 120).trim();
      const pubDate = dateMatch ? new Date(dateMatch[1]).getTime() : 0;
      const source = feedUrl.includes('socialmediaexaminer') ? 'SME' :
                     feedUrl.includes('anthropic') ? 'Anthropic' :
                     feedUrl.includes('openai') ? 'OpenAI' :
                     feedUrl.includes('venturebeat') ? 'VB' :
                     feedUrl.includes('theverge') ? 'Verge' :
                     feedUrl.includes('later') ? 'Later' :
                     feedUrl.includes('techcrunch') && feedUrl.includes('artificial') ? 'TC-AI' :
                     feedUrl.includes('techcrunch') ? 'TC' :
                     feedUrl.includes('buffer') ? 'Buffer' : 'WERSM';
      const aiSources = ['Anthropic','OpenAI','VB','Verge','TC-AI'];
      const isAI = aiSources.includes(source);
      const isInstagram = isAI || source !== 'Buffer' || 
        (title + ' ' + desc).toLowerCase().includes('instagram') ||
        (title + ' ' + desc).toLowerCase().includes('reels') ||
        (title + ' ' + desc).toLowerCase().includes('meta');
      if (title && link && isInstagram) {
        allArticles.push({ title, link, desc, pubDate, source });
      }
    }
  } catch (e) {}
}
allArticles.sort((a, b) => b.pubDate - a.pubDate);
const top5 = allArticles.slice(0, 10);

if (pickNum < 1 || pickNum > top5.length) {
  throw new Error('رقم غير صحيح. اختر من 1 إلى ' + top5.length);
}

const chosen = top5[pickNum - 1];
const topicText = chosen.title + ' - ' + chosen.desc + ' (المصدر: ' + chosen.link + ')';

return [{ json: { type: 'topic', originalText: topicText, chatId } }];

const editCmd = $('Parse Message').first().json.originalText.trim();
const chatId = $('Parse Message').first().json.chatId;

// Read all rows and find last draft
const rows = $input.all();
const drafts = rows.filter(r => r.json.status === 'draft');
if (!drafts.length) {
  return [{ json: { error: true, chatId, message: '⚠️ ما في كاروسيل جاهز للتعديل. أرسل موضوع أول.' } }];
}
const lastDraft = drafts[drafts.length - 1];
const rowId = lastDraft.json.id;

// Parse content JSON
let raw = lastDraft.json.content || '';
let start = raw.indexOf('{');
let end = raw.lastIndexOf('}');
let content;
try {
  content = JSON.parse(raw.substring(start, end + 1));
} catch(e) {
  return [{ json: { error: true, chatId, message: '⚠️ ما قدرت أقرأ المحتوى من الشيت.' } }];
}

// Parse the command
let slideNum = -1;
let field = '';
let newText = '';
let oldWord = '';
let isWordReplace = false;

const slideMatch = editCmd.match(/^s(\d+):\s*(.+)/i);
const captionMatch = editCmd.match(/^caption:\s*(.+)/i);
const hashtagsMatch = editCmd.match(/^hashtags:\s*(.+)/i);

if (slideMatch) {
  slideNum = parseInt(slideMatch[1]) - 1;
  const rest = slideMatch[2].trim();
  // Check if it's word replacement: old > new
  const replaceMatch = rest.match(/^(.+?)\s*>\s*(.+)$/);
  if (replaceMatch) {
    oldWord = replaceMatch[1].trim();
    newText = replaceMatch[2].trim();
    isWordReplace = true;
  } else {
    newText = rest;
  }
} else if (captionMatch) {
  content.caption = captionMatch[1].trim();
} else if (hashtagsMatch) {
  content.hashtags = hashtagsMatch[1].trim();
}

// Apply edit to slide
if (slideNum >= 0) {
  if (!content.slides || !content.slides[slideNum]) {
    return [{ json: { error: true, chatId, message: `⚠️ ما في سلايد رقم ${slideNum + 1}` } }];
  }
  const slide = content.slides[slideNum];

  if (isWordReplace) {
    // Replace old word in ALL text fields of this slide
    const replaceInObj = (obj) => {
      for (const key of Object.keys(obj)) {
        if (typeof obj[key] === 'string') {
          obj[key] = obj[key].split(oldWord).join(newText);
        } else if (Array.isArray(obj[key])) {
          obj[key] = obj[key].map(item =>
            typeof item === 'string' ? item.split(oldWord).join(newText) : item
          );
        }
      }
    };
    replaceInObj(slide);
  } else {
    // Replace main text based on slide type
    if (slide.type === 'cover') slide.title_line1 = newText;
    else if (slide.type === 'stat') slide.label = newText;
    else if (slide.type === 'one_liner') slide.text = newText;
    else if (slide.type === 'cta') slide.question = newText;
    else if (slide.title !== undefined) slide.title = newText;
    else if (slide.points) slide.points[0] = newText;
    else if (slide.steps) slide.steps[0] = newText;
    else if (slide.quote !== undefined) slide.quote = newText;
  }
}

const updatedContent = JSON.stringify(content);

return [{ json: { rowId, updatedContent, content, chatId, error: false } }];

const chatId = $('Apply Edit').first().json.chatId;
const content = $('Apply Edit').first().json.content;

const topic = content.topic || '';
let preview = '✏️ تم التعديل!\n\n';
preview += '📌 الموضوع: ' + topic + '\n';
preview += '🔢 عدد السلايدات: ' + content.slides.length + '\n\n';

content.slides.forEach((s, i) => {
  preview += '━━━ سلايد ' + (i+1) + ' (' + s.type + ') ━━━\n';

  if (s.type === 'cover') {
    if (s.eyebrow) preview += s.eyebrow + '\n';
    preview += (s.title_line1||'') + ' ' + (s.title_line2_grad||'') + ' ' + (s.title_line3||'') + '\n';
    if (s.pill) preview += '🏷 ' + s.pill + '\n';
  }
  else if (s.type === 'stat') {
    preview += '🔢 ' + (s.number||'') + '\n';
    preview += '📍 ' + (s.label||'') + '\n';
    if (s.description) preview += s.description + '\n';
  }
  else if (s.type === 'how_to') {
    preview += '📝 ' + (s.title||'') + '\n';
    (s.steps||[]).forEach((step, j) => { preview += (j+1) + '. ' + step + '\n'; });
  }
  else if (s.type === 'why_matters') {
    preview += '💡 ' + (s.title||'') + '\n';
    (s.points||[]).forEach((p, j) => { preview += (j+1) + '. ' + p + '\n'; });
  }
  else if (s.type === 'save') {
    preview += '🔖 ' + (s.title||'احفظ هالمعلومات') + '\n';
    (s.points||[]).forEach((p, j) => { preview += (j+1) + '. ' + p + '\n'; });
  }
  else if (s.type === 'warning') {
    preview += '⚠️ ' + (s.title||'انتبه!') + '\n';
    (s.points||[]).forEach((p, j) => { preview += (j+1) + '. ' + p + '\n'; });
  }
  else if (s.type === 'one_liner') {
    preview += '💬 ' + (s.text||'') + '\n';
  }
  else if (s.type === 'quote') {
    preview += '💬 "' + (s.quote||'') + '"\n';
    preview += '— ' + (s.author||'') + (s.role ? ' (' + s.role + ')' : '') + '\n';
  }
  else if (s.type === 'comparison') {
    preview += (s.col1_header||'') + ' vs ' + (s.col2_header||'') + '\n';
    (s.rows||[]).forEach(r => { preview += '• ' + r[0] + ' | ' + r[1] + '\n'; });
  }
  else if (s.type === 'cta') {
    preview += '❓ ' + (s.question||'') + '\n';
    if (s.options) s.options.forEach((o, j) => {
      preview += String.fromCharCode(65+j) + ') ' + o + '\n';
    });
  }
  preview += '\n';
});

if (content.caption) preview += '━━━ الكابشن ━━━\n' + content.caption + '\n\n';
if (content.hashtags) preview += '━━━ الهاشتاقات ━━━\n' + content.hashtags + '\n\n';

preview += '━━━━━━━━━━\n✅ عجبك؟ أرسل: موافق\n\n✏️ تبي تعدّل بعد؟\ns2: القديم > الجديد\ncaption: كابشن جديد';

return [{ json: { preview, chatId } }];

const topic = $json.originalText || "";

const text = topic.toLowerCase();

let trend = 60;
let viral = 60;

// كلمات تدل على ترند
const trendingWords = [
"جديد","ترند","خبر","أخيراً","الآن","اليوم",
"AI","ChatGPT","OpenAI","Meta","Instagram",
"TikTok","YouTube","Apple","Google","Elon"
];

trendingWords.forEach(word=>{
  if(text.includes(word.toLowerCase())){
    trend += 5;
    viral += 4;
  }
});

// الطول المناسب
if(topic.length > 40 && topic.length < 180){
    viral += 8;
}

// وجود أرقام
if(/\d/.test(topic)){
    viral += 5;
}

// وجود سؤال
if(topic.includes("؟") || topic.includes("?")){
    viral += 8;
}

// سقف أعلى
trend = Math.min(trend,100);
viral = Math.min(viral,100);

return [{
json:{
...$json,
trend_score:trend,
viral_score:viral
}
}];

