const chatId = $json.chatId || '';
const POOL = ["أصل أسماء الدول العربية ومعانيها", "كلمات عربية فصيحة نستخدمها يوميًا وما ندري", "حضارات قامت واندثرت في الجزيرة العربية", "أساطير وحكايات شعبية خليجية", "أغرب العادات الاجتماعية حول العالم", "معلومات عن اللغة العربية تدهشك", "شخصيات عربية غيّرت مجرى التاريخ", "أصل الأمثال الشعبية ومعانيها الحقيقية", "ألعاب شعبية قديمة قبل عصر الجوالات", "اختراعات لعلماء مسلمين سبقت عصرها", "أسرار الخط العربي وأنواعه", "مدن عربية تاريخية وقصصها", "معاني أسماء الأشهر الهجرية والميلادية", "تقاليد الضيافة في الثقافة العربية", "أطعمة شعبية والقصة وراء كل طبق", "علم الفلك عند العرب قديمًا", "لهجات عربية وكلمات تختلف معانيها بين الدول", "القصص وراء أسماء الأبراج", "تقاليد الأعراس حول الوطن العربي", "كنوز ومواقع أثرية في عُمان", "البحّارة والتجارة البحرية في تاريخ عُمان", "أدوات ومهن اندثرت مع الزمن", "معلومات جغرافية غريبة عن الوطن العربي", "أصل الأرقام العربية والهندية", "رموز الحيوانات والنباتات في الثقافة العربية", "قصص وراء أعلام الدول وألوانها", "طرق حساب الوقت عبر الحضارات", "شعراء عرب وقصائد خالدة", "أساطير القهوة العربية وطقوسها", "حصون وقلاع عُمان وقصصها"];
for (let i = POOL.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); const t = POOL[i]; POOL[i] = POOL[j]; POOL[j] = t; }
const pick = POOL.slice(0, 8);
let text = '💡 أفكار مواضيع ثقافية من فطين:\n\n';
pick.forEach((t, i) => { text += (i + 1) + '. ' + t + '\n'; });
text += '\n✍️ اختر أي فكرة، انسخها وأرسلها لي — أو اكتب موضوعك الخاص!';
return [{ json: { text, chatId } }];
